                    i += 1
                else_block = prompt_fmt[else_start:i-1]
            else:
                else_block = ""

            c = False
            if cond == "in_repo": c = in_repo
            elif cond == "in_remote": c = in_remote

            out += then_block if c else else_block
        else:
            out += prompt_fmt[i]
            i += 1

    prompt = out
    replacements = {
        r'\{username}': user,
        r'\{hostname}': host,
        r'\{current_dir}': cwd,
        r'\{repo_status}': repo_status or "",
        r'\{reset}': '\033[0m',
        r'\{bold}': '\033[1m',
        r'\{underline}': '\033[4m',
        r'\{red}': '\033[31m',
        r'\{blue}': '\033[34m',
        r'\{green}': '\033[32m',
        r'\{yellow}': '\033[33m',
        r'\{cyan}': '\033[36m',
        r'\{magenta}': '\033[35m',
        r'\n': '\n'
    }
    for k, v in replacements.items():
        prompt = prompt.replace(k, v)

    return prompt

def run_command(cmd_str):
    global aliases
    if not cmd_str.strip():
        return 0
    state_file = f"/tmp/nsh_state_{os.getpid()}_{time.time()}"
    alias_str = "\n".join(aliases)

    wrapper = f"""
{alias_str}
{cmd_str}
RET=$?
(
    echo "__PWD__"
    pwd
    echo "__ALIASES__"
    alias
    echo "__ENV__"
    env
) > {state_file}
exit $RET
"""
    ret = subprocess.call(["bash", "-O", "expand_aliases", "-c", wrapper])

    if not os.path.exists(state_file):
        sys.exit(ret)

    with open(state_file) as f:
        lines = f.read().splitlines()
    os.unlink(state_file)

    mode = None
    new_env = {}
    new_aliases = []
    new_pwd = ""
    for line in lines:
        if line == "__PWD__":
            mode = "pwd"
        elif line == "__ALIASES__":
            mode = "alias"
        elif line == "__ENV__":
            mode = "env"
        else:
            if mode == "pwd":
                new_pwd = line
            elif mode == "alias":
                new_aliases.append(line)
            elif mode == "env":
                if "=" in line:
                    k, v = line.split("=", 1)
                    new_env[k] = v

    try:
        os.chdir(new_pwd)
    except Exception:
        pass
    aliases.clear()
    aliases.extend(new_aliases)

    for k, v in new_env.items():
        if k not in ["_", "PWD", "OLDPWD", "SHLVL"]:
            os.environ[k] = v

    return ret

def setup_completer():
    try:
        bash_comp = subprocess.Popen(
            ['bash'],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            bufsize=1
        )

        bash_comp.stdin.write('''
        for f in /usr/local/etc/bash_completion.d/* /usr/etc/bash_completion.d/* /etc/bash_completion.d/*; do
            [ -f "$f" ] 2>/dev/null && source "$f" 2>/dev/null
        done
        function __nsh_complete() {
            local line="$1"
            local text="$2"
            local cmd=$(echo "$line" | awk '{print $1}')

            if [[ "$line" != *" "* ]]; then
                compgen -c -- "$text"
            else
                local rule=$(complete -p "$cmd" 2>/dev/null)
                if [[ -n "$rule" ]]; then
                    local args=${rule#complete }
                    args=${args% $cmd}
                    eval "compgen $args -- '$text'" 2>/dev/null
                else
                    compgen -f -- "$text"
                fi
            fi
            echo "__NSH_COMP_DONE__"
        }
        ''')
        bash_comp.stdin.flush()

        def completer(text, state):
            if state == 0:
                line = readline.get_line_buffer()
                bash_comp.stdin.write(f'__nsh_complete "{line}" "{text}"\n')
                bash_comp.stdin.flush()
                completer.matches = []
                while True:
                    l = bash_comp.stdout.readline().strip()
                    if l == "__NSH_COMP_DONE__":
                        break
                    completer.matches.append(l)
            if state < len(completer.matches):
                return completer.matches[state]
            return None

        readline.set_completer(completer)
        readline.set_completer_delims(" \t\n=\"\\'`@$><=;|&{(")
        readline.parse_and_bind("tab: complete")
    except Exception:
        pass

def load_history():
    hist_file = os.path.expanduser('~/.nsh_history')
    if os.path.exists(hist_file):
        try:
            with open(hist_file, 'r') as f:
                for line in f:
                    parts = line.strip().split('\t')
                    if len(parts) >= 3:
                        readline.add_history(parts[2])
        except Exception:
            pass

def append_history(cmd_str):
    hist_file = os.path.expanduser('~/.nsh_history')
    ts = int(time.time())
    cwd = os.getcwd()
    try:
        with open(hist_file, 'a') as f:
            f.write(f"{ts}\t{cwd}\t{cmd_str}\n")
        readline.add_history(cmd_str)
    except Exception:
        pass

def main():
    args = sys.argv[1:]
    norc = False
    command = None

    i = 0
    while i < len(args):
        if args[i] == '--version':
            print("nsh 0.1.0")
            return
        elif args[i] in ['-l', '--login']:
            pass
        elif args[i] == '--norc':
            norc = True
        elif args[i] == '-c':
            if i + 1 < len(args):
                command = args[i+1]
                i += 1
        elif not args[i].startswith('-'):
            command = f". {args[i]}"
        i += 1

    if not norc:
        nshrc_path = None
        if 'XDG_CONFIG_HOME' in os.environ:
            p = os.path.join(os.environ['XDG_CONFIG_HOME'], 'nsh/nshrc')
            if os.path.exists(p):
                nshrc_path = p
        if not nshrc_path:
            p = os.path.expanduser('~/.nshrc')
            if os.path.exists(p):
                nshrc_path = p
        if nshrc_path:
            run_command(f"source {nshrc_path} >/dev/null 2>&1")

    if command is not None:
        ret = run_command(command)
        sys.exit(ret)

    setup_completer()
    load_history()

    while True:
        prompt_fmt = os.environ.get("PROMPT", r"\{current_dir} \$ ")
        prompt = render_prompt(prompt_fmt)

        try:
            rl_prompt = re.sub(r'(\x1b\[[0-9;]*[a-zA-Z])', '\001\\1\002', prompt)
            line = input(rl_prompt)
        except EOFError:
            print("exit")
            break
        except KeyboardInterrupt:
            print()
            continue

        if line.strip():
            append_history(line.strip())
            run_command(line)

if __name__ == "__main__":
    main()
